"""Smooth reduced calibration movement, reactions solved from segment balance."""
import json,csv,numpy as np
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
from jump_rig import ROOT
from newton_euler_reference import body_wrenches,external_wrenches,accumulate,at_point,energy
OUT=ROOT/'results/mechanics_foundation';CFG=json.loads((ROOT/'scenarios/planar_calibration.json').read_text('utf-8'))

def state(t,upper_com=None):
    c=CFG;M=c['mass_kg'];g=c['gravity_m_s2'];T=c['duration_s'];u=np.pi*t/T;s=np.sin(u);co=np.cos(u);rate=np.pi/T;A=c['theta_excursion_rad'];q=c['theta_start_rad']+A*s**4;v=4*A*rate*s**3*co;a=4*A*rate**2*(3*s*s*co*co-s**4)
    Ls=c['shank_length_m'];Lt=c['thigh_length_m'];ankle=np.array([0.,0,c['ankle_height_m']]);rs=np.array([Ls*np.sin(q),0,Ls*np.cos(q)]);rt=np.array([-Lt*np.sin(q),0,Lt*np.cos(q)]);vs=Ls*v*np.array([np.cos(q),0,-np.sin(q)]);vt=Lt*v*np.array([-np.cos(q),0,-np.sin(q)]);aas=Ls*np.array([a*np.cos(q)-v*v*np.sin(q),0,-a*np.sin(q)-v*v*np.cos(q)]);aat=Lt*np.array([-a*np.cos(q)+v*v*np.sin(q),0,-a*np.sin(q)-v*v*np.cos(q)]);knee=ankle+rs;hip=knee+rt
    p=c['reference_parameters'];ms=M*p['male_shank']['mass_fraction'];mt=M*p['male_thigh']['mass_fraction'];mf=M*p['male_foot']['mass_fraction'];mu=M/2-ms-mt-mf;mass=np.array([0,mf,ms,mt,mu]);fs=1-p['male_shank']['proximal_COM_fraction'];ft=1-p['male_thigh']['proximal_COM_fraction'];footL=c['foot_support_x_m'][1]-c['foot_support_x_m'][0];footCOM=c['foot_support_x_m'][0]+p['male_foot']['heel_COM_fraction']*footL;h=c['upper_COM_from_hip_m'] if upper_com is None else upper_com;lean=c['upper_constant_lean_rad'];com=np.array([[0,0,0],[footCOM,0,.035],ankle+fs*rs,knee+ft*rt,hip+[h*np.sin(lean),0,h*np.cos(lean)]]);vel=np.array([[0,0,0],[0,0,0],fs*vs,vs+ft*vt,vs+vt]);acc=np.array([[0,0,0],[0,0,0],fs*aas,aas+ft*aat,aas+aat]);omega=np.zeros((5,3));alpha=omega.copy();omega[2,1]=v;omega[3,1]=-v;alpha[2,1]=a;alpha[3,1]=-a;I=np.zeros((5,3,3))
    for i,key,L,ang in [(1,'male_foot',footL,np.pi/2),(2,'male_shank',Ls,q),(3,'male_thigh',Lt,-q)]:
        k=np.array(p[key]['k_xyz']);R=np.array([[np.cos(ang),0,np.sin(ang)],[0,1,0],[-np.sin(ang),0,np.cos(ang)]]);I[i]=R@np.diag(mass[i]*(k*L)**2)@R.T
    I[4]=np.diag(mu*np.array([.2,.2,.1])**2) # inactive: upper omega and alpha are zero
    own=body_wrenches(mass,com,I,acc,omega,alpha,[0,0,-g]);required=own.sum(axis=0);F=required[:3];cop=-required[4]/F[2];ext=external_wrenches(5,[(1,np.array([cop,0,0]),F,np.zeros(3))]);w=accumulate([0,0,1,2,3],own-ext);cuts=[at_point(w[i],point) for i,point in [(2,ankle),(3,knee),(4,hip)]];tau=np.array([x[4] for x in cuts]);relative=np.array([v,-2*v,v]);P=2*float(tau@relative);E=2*energy(mass,com,I,vel,omega,[0,0,-g]);bodyrate=2*float(np.sum(mass[:,None]*(acc-[0,0,-g])*vel)+np.einsum('bi,bij,bj->',omega,I,alpha));lo,hi=c['foot_support_x_m'];heel=F[2]*(hi-cop)/(hi-lo);toe=F[2]*(cop-lo)/(hi-lo)
    return {'theta':q,'joints':np.array([ankle,knee,hip]),'upper_COM':com[4],'F_total':2*F,'COP_x':cop,'joint_moments':tau,'net_joint_reactions':np.array([x[:3] for x in cuts]),'total_joint_power':P,'energy':E,'body_energy_rate':bodyrate,'root_residual':w[0],'heel_normal_each':heel,'toe_normal_each':toe}

def run():
    OUT.mkdir(exist_ok=True,parents=True);T=CFG['duration_s'];studies=[];finest=None
    for hz in [100,200,400,800]:
        ts=np.linspace(0,T,round(T*hz)+1);rows=[state(float(t)) for t in ts];F=np.array([r['F_total'] for r in rows]);cop=np.array([r['COP_x'] for r in rows]);tau=np.array([r['joint_moments'] for r in rows]);P=np.array([r['total_joint_power'] for r in rows]);E=np.array([r['energy'] for r in rows]);rate=np.array([r['body_energy_rate'] for r in rows]);fd=np.gradient(E,ts,edge_order=2);mid=len(ts)//2;down=float(np.trapezoid(P[:mid+1],ts[:mid+1]));up=float(np.trapezoid(P[mid:],ts[mid:]));err=max(abs(down-(E[mid]-E[0])),abs(up-(E[-1]-E[mid])));rms=float(np.sqrt(np.mean((fd-rate)**2))/max(1,np.sqrt(np.mean(rate**2))));root=float(max(abs(r['root_residual']).max() for r in rows));heel=min(r['heel_normal_each'] for r in rows);toe=min(r['toe_normal_each'] for r in rows);friction=float(np.max(abs(F[:,0])/F[:,2]));item={'hz':hz,'work_energy_error_each_half_J':err,'energy_derivative_relative_RMS_error':rms,'joint_power_vs_body_energy_rate_max_W':float(abs(P-rate).max()),'root_wrench_component_residual_max_SI':root,'minimum_heel_normal_each_N':heel,'minimum_toe_normal_each_N':toe,'maximum_required_friction_ratio':friction,'minimum_vertical_support_N':float(F[:,2].min()),'COP_range_x_m':[float(cop.min()),float(cop.max())],'peak_joint_moments_abs_Nm':np.max(abs(tau),axis=0).tolist(),'work_down_J':down,'work_up_J':up};studies.append(item)
        if hz==800:finest=(ts,rows,F,cop,tau,P,E)
    last=studies[-1];gates={'root_balance':last['root_wrench_component_residual_max_SI']<1e-7,'power_identity':last['joint_power_vs_body_energy_rate_max_W']<1e-7,'half_cycle_work_energy':last['work_energy_error_each_half_J']<.01,'finite_difference_energy_rate':last['energy_derivative_relative_RMS_error']<.001,'unilateral_contact':min(last['minimum_heel_normal_each_N'],last['minimum_toe_normal_each_N'])>=0,'friction':last['maximum_required_friction_ratio']<=CFG['friction_coefficient_assumed'],'support_positive':last['minimum_vertical_support_N']>0};sensitivity=[]
    for h in [.25,.30,.35]:
        rr=[state(float(t),h) for t in np.linspace(0,T,501)];sensitivity.append({'upper_COM_distance_from_hip_m':h,'peak_moments_abs_Nm':np.max(abs(np.array([r['joint_moments'] for r in rr])),axis=0).tolist()})
    qmin=CFG['theta_start_rad'];qmax=qmin+CFG['theta_excursion_rad'];ranges={'ankle':[qmin,qmax],'knee_flexion':[2*qmin,2*qmax],'hip_flexion':[qmin+CFG['upper_constant_lean_rad'],qmax+CFG['upper_constant_lean_rad']]};gates['declared_design_ROM']=all(v[0]>=CFG['declared_planar_design_limits_rad'][k][0] and v[1]<=CFG['declared_planar_design_limits_rad'][k][1] for k,v in ranges.items())
    report={'status':'verified_planar_calibration' if all(gates.values()) else 'calibration_failed','human_movement_validated':False,'muscle_forces_inferred':False,'model':'symmetric planar two-leg chain with a rigid lumped upper body, constant upper orientation','contact_loads':'derived from all segment inertial/gravity wrenches; equal left-right support sharing','joint_load_definition':'net sagittal intersegmental moments; not articular contact forces','parameter_policy':CFG,'coordinate_ranges_rad':ranges,'ROM_envelope_is_individual_measurement':False,'resolution':studies,'gates':{k:bool(v) for k,v in gates.items()},'upper_COM_sensitivity_scenarios_not_confidence_intervals':sensitivity}
    (OUT/'planar_calibration.json').write_text(json.dumps(report,indent=2),encoding='utf-8');ts,rows,F,cop,tau,P,E=finest;np.savez_compressed(OUT/'planar_calibration.npz',times=ts,GRF_N=F,COP_x_m=cop,joint_moments_Nm=tau,joint_power_W=P,energy_J=E)
    with (OUT/'planar_calibration.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f);w.writerow(['time_s','GRF_forward_N','GRF_up_N','COP_x_m','ankle_net_Nm','knee_net_Nm','hip_net_Nm','total_joint_power_W','body_energy_J']);w.writerows(zip(ts,F[:,0],F[:,2],cop,tau[:,0],tau[:,1],tau[:,2],P,E))
    draw_plot(finest,report);print(json.dumps({'status':report['status'],'gates':report['gates'],'finest':last}),flush=True)

def draw_plot(data,report):
    ts,rows,F,cop,tau,P,E=data;im=Image.new('RGB',(1500,1120),'#101c2b');d=ImageDraw.Draw(im);font=lambda n:ImageFont.truetype('C:/Windows/Fonts/arial.ttf',n);d.text((65,30),'REDUCED CALIBRATION / REACTIONS SOLVED FROM BALANCE',font=font(30),fill='#edf3fb');d.text((65,80),'Smooth squat / 90 kg reference assumptions / net joint loads / no muscle inference',font=font(23),fill='#b5c7d8')
    for k,(title,series) in enumerate([('Ground reaction / N',[('Vertical',F[:,2],'#8ce2d5'),('Forward',F[:,0],'#84bdf4')]),('COP forward position / m',[('COP',cop,'#8ce2d5')]),('Right net joint moments / Nm',[('Ankle',tau[:,0],'#84bdf4'),('Knee',tau[:,1],'#8ce2d5'),('Hip',tau[:,2],'#c5b5ff')])]):
        x0,x1=145,1425;y0=200+k*280;y1=y0+170;vv=np.concatenate([v for _,v,_ in series]);lo=min(0,float(vv.min()));hi=max(.01,float(vv.max()));pad=.07*(hi-lo);lo-=pad;hi+=pad;X=lambda t:x0+(x1-x0)*t/ts[-1];Y=lambda v:y1-(y1-y0)*(v-lo)/(hi-lo);d.text((65,y0-45),title,font=font(25),fill='#edf3fb')
        for v in np.unique([lo,0,hi]):d.line((x0,Y(v),x1,Y(v)),fill='#344b60');d.text((x0-14,Y(v)),f'{v:.3g}',font=font(21),fill='#b5c7d8',anchor='rm')
        for label,y,c in series:d.line([(X(float(t)),Y(float(v))) for t,v in zip(ts[::3],y[::3])],fill=c,width=3)
        pos=930
        for label,_,c in series:d.text((pos,y0-40),label,font=font(21),fill=c);pos+=160
        for t in [0,.5,1,1.5,2,2.5]:d.text((X(t),y1+13),f'{t:.1f}s',font=font(21),fill='#b5c7d8',anchor='mt')
    d.text((65,1065),'Population parameters + explicit idealizations; verified mechanics, not individualized biological accuracy.',font=font(23),fill='#edb580');im.save(OUT/'planar_calibration.png')
if __name__=='__main__':run()
